def is_multiply_prime(a):
    if a < 2:
        return False
    count = 0
    n = a
    # Check factor 2
    while n % 2 == 0:
        count += 1
        n //= 2
    # Check odd factors from 3 upward
    f = 3
    while f * f <= n:
        while n % f == 0:
            count += 1
            n //= f
        f += 2
    # If n > 1, then it's a prime factor
    if n > 1:
        count += 1
    return count == 3

